        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var brandMult = ds.brandEquity / 50;
            var marketingMult = 1 + (d.marketingBudget / 500) * 0.25;
            var tradePromoMult = 1 + (d.tradePromoBudget / 400) * 0.15;

            var rdQualityBoost = d.rdInvestment / 80;

            var eventMod = { priceSensitive: 1, brandLoyal: 1, premium: 1, modernTradeBonus: 0 };
            if (period === 2) {
                eventMod.premium = 0.88;
                eventMod.brandLoyal = 0.95;
            }
            if (period === 3) {
                eventMod.modernTradeBonus = 0.10;
            }

            var prices = {
                priceSensitive: d.priceEconomy,
                brandLoyal: d.priceStandard,
                premium: d.pricePremium
            };

            var shares = {
                priceSensitive: ds.marketSharePrice,
                brandLoyal: ds.marketShareBrand,
                premium: ds.marketSharePremium
            };

            var segKeys = ['priceSensitive', 'brandLoyal', 'premium'];
            var segSales = {};
            var segRevenue = {};
            var totalSales = 0;
            var totalRevenue = 0;

            for (var i = 0; i < segKeys.length; i++) {
                var seg = segKeys[i];
                var info = this.SEGMENTS[seg];
                var priceRatio = info.compAvgPrice / prices[seg];
                var priceElastMult = Math.pow(priceRatio, Math.abs(info.elasticity));

                var qualityMult = 1 + rdQualityBoost * (seg === 'premium' ? 0.15 : (seg === 'brandLoyal' ? 0.08 : 0.03));

                var channelMult = 1;
                if (seg === 'premium' || seg === 'brandLoyal') {
                    channelMult = 1 + (d.modernTradeAlloc - 50) / 200;
                } else {
                    channelMult = 1 + (50 - d.modernTradeAlloc) / 300;
                }

                var evMod = eventMod[seg] || 1;

                var adjustedShare = shares[seg] * priceElastMult * marketingMult * brandMult * qualityMult * tradePromoMult * channelMult * evMod;
                adjustedShare = Math.max(2, Math.min(40, adjustedShare));

                var demand = info.size * (adjustedShare / 100);
                segSales[seg] = demand;
                segRevenue[seg] = demand * prices[seg];
                totalSales += demand;
                totalRevenue += demand * prices[seg];

                shares[seg] = Math.round(adjustedShare * 10) / 10;
            }

            var available = ds.inventory + d.productionVolume;
            var actualSalesRatio = 1;
            if (totalSales > available) {
                actualSalesRatio = available / totalSales;
                totalSales = available;
                totalRevenue = totalRevenue * actualSalesRatio;
            }

            var variableCost = 0.35;
            var fixedManufacturing = 100;
            var scaleEffect = 1 - (d.productionVolume - 400) / 8000;
            scaleEffect = Math.max(0.85, Math.min(1.0, scaleEffect));
            var effectiveVarCost = variableCost * scaleEffect;
            var cogs = totalSales * effectiveVarCost + fixedManufacturing;

            var grossProfit = totalRevenue - cogs;
            var grossMarginPct = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;

            var salesForceCost = 35 + (d.modernTradeAlloc / 100) * 20 + ((100 - d.modernTradeAlloc) / 100) * 25;
            var logisticsCost = totalSales * 0.02 + (100 - d.modernTradeAlloc) * 0.3;

            var totalOpex = d.marketingBudget + d.tradePromoBudget + d.rdInvestment + salesForceCost + logisticsCost;
            var operatingProfit = grossProfit - totalOpex;

            var endingInventory = available - totalSales;
            var spoilageRate = 0.02 + Math.max(0, endingInventory - 100) * 0.0003;
            var spoilage = endingInventory * spoilageRate;
            endingInventory = Math.max(0, endingInventory - spoilage);

            var holdingCost = endingInventory * effectiveVarCost * 0.02;
            operatingProfit -= holdingCost;
            operatingProfit -= spoilage * effectiveVarCost;

            var incrementalVolumeFromPromo = totalSales * (tradePromoMult - 1);
            var incrementalMargin = incrementalVolumeFromPromo * (totalRevenue / totalSales - effectiveVarCost);
            var promoROI = d.tradePromoBudget > 0 ? ((incrementalMargin - d.tradePromoBudget) / d.tradePromoBudget) * 100 : 0;

            var brandDelta = (d.marketingBudget / 50) * 2 + (d.rdInvestment / 30) * 1.5 - (d.tradePromoBudget / 100) * 1 + (rdQualityBoost * 3);
            if (period === 2 && d.rdInvestment >= 40) brandDelta += 5;
            var newBrandEquity = Math.max(10, Math.min(100, ds.brandEquity + brandDelta));

            var totalShare = (shares.priceSensitive * 2100 + shares.brandLoyal * 1400 + shares.premium * 800) / 4300;

            var baselineShare = (ds.marketSharePrice * 2100 + ds.marketShareBrand * 1400 + ds.marketSharePremium * 800) / 4300;
            var shareDelta = totalShare - baselineShare;

            var spoilagePct = (available > 0) ? (spoilage / available) * 100 : 0;
            var inventoryEfficiency = 100 - spoilagePct * 5;
            inventoryEfficiency = Math.max(0, Math.min(100, inventoryEfficiency));

            var cogsRatio = totalRevenue > 0 ? (cogs / totalRevenue) * 100 : 100;
            var productionEfficiency = Math.max(0, 100 - cogsRatio);

            var mpi = 0;
            mpi += Math.min(25, Math.max(0, operatingProfit / 4)) * 0.25;
            mpi += Math.min(25, totalShare * 0.625) * 0.20;
            mpi += Math.min(25, newBrandEquity * 0.25) * 0.20;
            mpi += Math.min(25, Math.max(0, operatingProfit / 3)) * 0.15;
            mpi += Math.min(25, inventoryEfficiency * 0.25) * 0.10;
            mpi += Math.min(25, productionEfficiency * 0.25) * 0.10;

            if (shareDelta < -3) mpi -= 10;
            if (spoilagePct > 5) mpi -= 5;
            if (actualSalesRatio < 1) mpi -= 10;

            mpi = Math.round(Math.max(0, mpi) * 10) / 10;

            ds.cash += operatingProfit;
            ds.totalProfit += operatingProfit;
            ds.inventory = Math.round(endingInventory);
            ds.marketSharePrice = shares.priceSensitive;
            ds.marketShareBrand = shares.brandLoyal;
            ds.marketSharePremium = shares.premium;
            ds.brandEquity = Math.round(newBrandEquity * 10) / 10;
            ds.cumulativeMarketing += d.marketingBudget;
            ds.cumulativeRD += d.rdInvestment;

            ds.profitHistory.push(Math.round(operatingProfit * 10) / 10);
            ds.shareHistory.push(Math.round(totalShare * 10) / 10);
            ds.brandHistory.push(Math.round(newBrandEquity * 10) / 10);
            ds.revenueHistory.push(Math.round(totalRevenue * 10) / 10);
            ds.cashHistory.push(Math.round(ds.cash * 10) / 10);

            /* platform score: this sim own Market Performance Index, native scale 0-25, rescaled to 0-100 */
