        _updateEventBanner(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.EVENTS.length - 1);
            var evt = this.EVENTS[idx];
            var banner = document.getElementById('eventBanner');
            var text = document.getElementById('eventText');
            if (banner && text) {
                if (evt && evt.key) {
                    banner.style.display = 'block';
                    text.innerHTML = window.mySimulation ? window.mySimulation.t(evt.key) : '';
                } else {
                    banner.style.display = 'none';
                    text.innerHTML = '';
                }
            }
        }
    }

